// Educational models. None of these inputs are Anthropic's share price or forecast.
export function shareScenario(price=25,newMillions=2){
 const p=Number(price),n=Number(newMillions);
 if(!Number.isFinite(p)||p<=0||!Number.isFinite(n)||n<0)throw new RangeError('Positive price and nonnegative issuance required');
 const existingMillions=10,totalMillions=existingMillions+n;
 return {price:p,newMillions:n,totalMillions,preValueMillions:p*existingMillions,postValueMillions:p*totalMillions,raisedMillions:p*n,previousOnePercent:existingMillions/totalMillions};
}
export function timeScenario(minutes=20,savingPercent=40,reviewMinutes=5,tasks=10){
 const values=[minutes,savingPercent,reviewMinutes,tasks].map(Number);
 if(values.some(v=>!Number.isFinite(v))||values[0]<0||values[1]<0||values[1]>100||values[2]<0||values[3]<0)throw new RangeError('Invalid time scenario');
 const [m,p,r,t]=values;return {baseline:m*t,assisted:(m*(1-p/100)+r)*t,netSaved:(m*p/100-r)*t};
}
